head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/elw_recv_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vBzTpCd;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_co_list_sync = function() {
    var url = "/ElwListedReceive.do?method=listElwInfoCoList&inputMessageId=ELW_LISTING_PROC_INOUT";
    url += "&LIST_BZ_TP_CD=" + scwin.vBzTpCd;
    dts_CoList.DataID = encodeURI(url);
    dts_CoList.Reset();
    $c.cm.ShowWin(grd_CoList);
};
scwin.fn_isu_list_sync = function(obj) {
    var vIsurCd = dts_CoList.getCellData(eval(obj), "ISUR_CD");
    var url = "/ElwListedReceive.do?method=listElwInfoIsuList&inputMessageId=ELW_LISTING_PROC_INOUT";
    url += "&LIST_BZ_TP_CD=" + scwin.vBzTpCd;
    url += "&ISUR_CD=" + vIsurCd;
    dts_IsuList.DataID = encodeURI(url);
    dts_IsuList.Reset();
    $c.cm.ShowWin(grd_IsuList);
};
scwin.fn_dscl = async function() {
    if (dts_IsuList.getTotalRow() == 0) {
        $c.win.alert("[종목현황] 목록에서 선택해주세요");
        return;
    }
    var vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
    if (vBzProcsNo.length != 14) {
        $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }
    var vIsurCd = dts_CoList.getCellData(dts_CoList.getRowPosition(), "ISUR_CD");
    var vComNm = dts_CoList.getCellData(dts_CoList.getRowPosition(), "COM_NM");
    var vListDd = dts_CoList.getCellData(dts_CoList.getRowPosition(), "LIST_DD");
    var vDsclTtl;
    var vDsclCtnt;
    var vBzTpNm;
    var vFormCd;
    if (scwin.vBzTpCd == LIST_BZ_TP_CD_003) {
        vBzTpNm = "신규상장";
        vFormCd = "68951";
    } else if (scwin.vBzTpCd == LIST_BZ_TP_CD_005) {
        vBzTpNm = "추가상장";
        vFormCd = "68952";
    }
    var arrPar = new Array();
    for (var i = 1, p = 0; i <= dts_IsuList.getTotalRow();
        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************
        i++, p++) {
        arrPar[p] = dts_IsuList.getCellData(i, "ISU_ABBRV2");
    }
    var arrIsuStr = $c.elw.fn_getArrIsuNmInfo(arrPar);
    vDsclTtl = "" + vComNm + " (상장일 " + vListDd.substring(0, 4) + "." + vListDd.substring(4, 6) + "." + vListDd.substring(6, 8) + ")" + "";
    vDsclCtnt = vComNm + "가 발행한 주식워런트증권 ";
    //OO증권(주)가 발행한 주식워런트증권 제OOOO호 내지 제OOOO호 00개 종목이 2006년 0월00일 신규상장됩니다.
    vDsclCtnt += "" + arrIsuStr[0].ISUR_STR + " ";
    vDsclCtnt += "총 " + arrIsuStr[0].ISUR_CNT + "개종목이 " + vListDd.substring(0, 4) + "년" + vListDd.substring(4, 6) + "월" + vListDd.substring(6, 8) + "일 " + vBzTpNm + "됩니다.";
    vDsclCtnt += "\r\n";
    vDsclCtnt += "\r\n";
    vDsclCtnt += "기타 자세한 내역은 한국거래소 홈페이지 (http://www.krx.co.kr) 공지사항을 참조하시기 바랍니다.";

    //alert('[vDsclTtl]'+vDsclTtl);
    //alert('[vDsclCtnt]'+vDsclCtnt);
    //alert('[vBzProcsNo]'+vBzProcsNo);
    /*
    	if(  dts_Mst.IsUpdated || dts_Isu.IsUpdated || dts_Rsn.IsUpdated ) {
    		alert(getMessageParam("MSG-0022", ""));
    		return ;
    	}
    */
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = vFormCd;
        arr[1] = vBzProcsNo; //테스트할때는 첫번째 업무처리번호를 일단 넘긴다...
        arr[2] = vIsurCd;
        arr[3] = '1';
        arr[4] = vDsclCtnt;
        arr[5] = vDsclTtl;
        $c.stf.CopyDataSet(dts_IsuList, param_dts_isu);
        //CopyDataSet( dts_Isu , param_dts_mst) ;
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 730 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.btn_Dscl_onclick = function() {
    scwin.fn_dscl();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.grd_CoList_OnClick = function(row, colid) {
    scwin.fn_isu_list_sync(row);
};
scwin.dts_CoList_OnLoadError = function() {
    $c.stf.alert_error(dts_CoList);
};
scwin.dts_CoList_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_CoList);
};
scwin.dts_IsuList_OnLoadError = function() {
    $c.stf.alert_error(dts_IsuList);
};
scwin.dts_IsuList_OnLoadCompleted = function(rowcount) {
    edt_IsuTotalCnt.setValue("총 " + dts_IsuList.getTotalRow() + " 건");
    $c.cm.CloseWin(rowcount, grd_IsuList);
};
scwin.gform_onload = function() {
    var parentWin = $c.frame.path("../");
    scwin.vBzTpCd = parentWin.fn_getbzTpCd();
    scwin.fn_co_list_sync();
};
